EXPECTED_CASES = tuple(json.loads(_EXPECTED_JSON))


def verify_pinned_case(prompt, oracle):
    if (
        type(prompt) is not dict
        or set(prompt) != {"case_id", "prompt", "entry_point"}
        or type(oracle) is not dict
        or set(oracle) != {"case_id", "test", "canonical_solution"}
    ):
        raise ValueError("fixed official prompt/oracle fields required")
    if any(type(value) is not str for value in (*prompt.values(), *oracle.values())):
        raise ValueError("fixed official case strings required")
    index = next((i for i, row in enumerate(EXPECTED_CASES) if row["case_id"] == prompt["case_id"]), None)
    if index is None or oracle["case_id"] != prompt["case_id"]:
        raise ValueError("fixed official case ID differs")
    expected = EXPECTED_CASES[index]

    def canonical(value):
        return json.dumps(
            value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
        ).encode()

    if (
        hashlib.sha256(canonical(prompt)).hexdigest() != expected["prompt_record_sha256"]
        or hashlib.sha256(canonical(oracle)).hexdigest() != expected["oracle_record_sha256"]
    ):
        raise ValueError("fixed official case bytes differ")
    return expected
